        "enum": ["灵感激发", "配方选择", "写作准备确认", "开篇审阅", "结局类型确认"], 
        "type": "string"
    },
    "summary": {
        "anyOf": [{"type": "string"}, {"type": "null"}], 
        "description": "确认模式下的总结信息，或询问模式下的当前进度描述"
    },
    "type": {
        "description": "交互类型：confirmation（确认）或 question（询问）", 
        "enum": ["confirmation", "question"], 
        "type": "string"
    }
