{"path":"outline.json","content":"{
  "act_one": {
    "description": "建立1992年时代背景，引入陈程和林宁的雇佣关系，展示公路旅行的艰辛和枕巾的象征意义。通过物件（枕巾、边斗、红丝巾）建立情感暗涌。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第一天：出发",
        "core_event": "陈程雇佣林宁押货，从南方出发。第一个县城，他买了一对鸳鸯枕巾，她以为只是商品。",
        "emotional_tone": "疏离、试探",
        "key_scenes": [
          "陈程骑嘉陵摩托停在国营厂门口，林宁背着包袱上车",
          "第一个县城供销社，陈程买第一对枕巾，林宁疑惑",
          "夜晚露宿，林宁在地图上标记第一个城市"
        ]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第二天：风雨",
        "core_event": "暴风雨中，陈程停车给她买红丝巾。枕巾盖在他们头上避雨，边斗成为临时避风港。",
        "emotional_tone": "温暖、暗涌",
        "key_scenes": [
          "暴风雨来临，摩托车在风雨中艰难前行",
          "陈程突然停车，跑进供销社买红丝巾",
          "两人躲在边斗里，枕巾盖在头上，第一次身体接触"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "第三天：地图上的心",
        "core_event": "林宁偷偷在地图上画心，陈程发现但没有说破。枕巾已经堆满边斗的一半。",
        "emotional_tone": "甜蜜、压抑",
        "key_scenes": [
          "经过第三个县城，陈程又买了一对枕巾",
          "林宁趁陈程不在，在地图上画心",
          "陈程看到地图上的心，嘴角上扬但没有说破"
        ]
      }
    ],
    "turning_point": "第三天夜晚，陈程在桥洞下把所有枕巾铺开，说'现在我们有一万张婚床'。林宁第一次意识到，这可能不只是雇佣关系。"
  },
  "act_two": {
    "description": "情感在旅途中发酵，枕巾从商品变成聘礼，边斗从货仓变成婚房。商业困境逐渐显现，陈程的宿命感越来越强。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "第四天：婚床",
        "core_event": "桥洞下，陈程把所有枕巾铺开当床。两人第一次真正靠近，但都没有捅破那层纸。",
        "emotional_tone": "浪漫、压抑",
        "key_scenes": [
          "夜晚桥洞下，陈程铺开所有枕巾",
          "两人躺在枕巾上，看着星空",
          "陈程想说的话到了嘴边，又咽了回去"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第五天：困境",
        "core_event": "货物滞销，陈程开始焦虑。林宁发现他在偷偷数钱，知道生意不好。",
        "emotional_tone": "焦虑、担忧",
        "key_scenes": [
          "第五个县城，货物卖不出去",
          "陈程在角落里数钱，眉头紧锁",
          "林宁想安慰他，但不知道该说什么"
        ]
      },
      {
        "chapter_number": 6,
        "chapter_title": "第六天：誓言",
        "core_event": "陈程告诉林宁：'如果这单赚了，我娶你；如果赔了，摩托归你，我归摩托。'林宁以为他在开玩笑。",
        "emotional_tone": "悲壮、宿命",
        "key_scenes": [
          "第六个县城，生意依然不好",
          "陈程在夕阳下说出那句话",
          "林宁笑了，以为他在开玩笑，但心里有一丝不安"
        ]
      }
    ],
    "turning_point": "第六天夜晚，陈程偷偷卖掉了一部分货物，换来的钱不够买去深圳的车票，但够买一对枕巾。他买了最后第七对枕巾，完成了这场'流浪婚礼'的仪式。"
  },
  "act_three": {
    "description": "商业彻底失败，陈程选择'归摩托'（死在路上）。林宁卖摩托买深圳车票，但陈程死在去深圳的路上。她拿着两张车票，一张是自己的新生，一张是他的遗物。",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "第七天：结局",
        "core_event": "生意彻底失败。陈程把摩托留给林宁，自己选择'归摩托'。林宁卖掉摩托，买了两张去深圳的车票，但陈程已经死在路上。",
        "emotional_tone": "绝望、悲剧",
        "key_scenes": [
          "第七天，生意彻底失败，陈程把摩托钥匙交给林宁",
          "陈程说'摩托归你，我归摩托'，然后消失在夜色中",
          "林宁卖掉摩托，买了两张去深圳的车票",
          "在火车站，林宁等不到陈程，只等到一个陌生人送来的消息：他在路上出事了",
          "林宁拿着两张车票，一张是自己的新生，一张是他的遗物",
          "她独自上了火车，带着所有枕巾，去往深圳"
        ]
      }
    ],
    "turning_point": "最后一句：火车开动时，林宁看着窗外，枕巾上的鸳鸯图案在阳光下泛着光。她终于明白，他用七天七夜，给她铺了一万张婚床，却只换来她一个人去深圳的车票。"
  }
}"}

